.ds-passport-example{--surface:var(--white,#FFFFFF);--surface-subtle:var(--cream,#F5F3EE);--surface-soft:var(--sage,#DDE6D8);--surface-ink:var(--forest,#1B3A28);--surface-muted:var(--muted,#5B6D60);--radius-card:16px;--radius-control:12px;width:620px;max-width:100%;padding:28px;border-radius:16px;background:#EDF1EA;color:var(--surface-ink);font-family:var(--font-ui,"Plus Jakarta Sans",Arial,sans-serif);line-height:1.6;box-sizing:border-box;}.ds-passport-example *{box-sizing:border-box;}.ds-passport-example h3{margin:0;font-size:28px;line-height:1.2;font-style:italic;font-weight:500;letter-spacing:-.035em;}.ds-passport-example>p{max-width:42ch;margin:13px 0 0;color:var(--surface-muted);font-size:14px;}.ds-passport-example button,.ds-passport-example a{font-family:inherit;}.ds-passport-example a{color:inherit;text-decoration:none;}.ds-passport-example a:hover{text-decoration:underline;}.ds-passport-example :focus-visible{outline:3px solid var(--green,#2D5E3A);outline-offset:4px;}.ds-passport-stack-card{box-shadow:none;}.ds-passport-stack { margin-top: 28px; }
.ds-passport-stack-stage { position: relative; height: 352px; isolation: isolate; }
.ds-passport-stack-card { position: absolute; top: 88px; left: 0; width: 100%; height: 264px; border-radius: var(--radius-card); background: var(--surface); transform: translateY(var(--stack-shift)) scale(var(--stack-scale)); transform-origin: center top; transition: transform 350ms cubic-bezier(.16, 1, .3, 1), background-color 200ms ease; }
.ds-passport-stack-card[data-layer="1"] { background: #F7F9F5; }
.ds-passport-stack-card[data-layer="2"] { background: #F2F5EF; }
.ds-passport-stack-trigger { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%; min-height: var(--stack-tab-height); padding: 8px 16px; border: 0; border-radius: var(--radius-card) var(--radius-card) 0 0; background: transparent; color: var(--surface-ink); text-align: left; font-size: 13px; font-weight: 600; cursor: pointer; }
.ds-passport-stack-trigger:hover { background: var(--surface-soft); }
.ds-passport-stack-number { flex: 0 0 auto; font-size: 15px; font-weight: 500; font-variant-numeric: tabular-nums; }
.ds-passport-stack-content { height: 220px; padding: 0 8px 8px; }
.ds-passport-stack-content[hidden] { display: none; }
.ds-passport-stack-profile { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 16px; }
.ds-passport-stack-profile > img { width: 100%; height: 100%; min-height: 0; object-fit: cover; border-radius: var(--radius-control); }
.ds-passport-stack-identity { display: flex; flex-direction: column; min-width: 0; padding: 12px 8px 8px 0; }
.ds-passport-stack-identity strong { font-size: clamp(18px, 1.8vw, 25px); font-weight: 600; line-height: 1.2; letter-spacing: -.025em; }
.ds-passport-stack-identity > span { margin-top: 8px; font-size: 12px; color: var(--surface-muted); }
.ds-passport-stack-identity > .ds-passport-stack-year { margin-top: 18px; color: var(--surface-ink); font-size: 24px; line-height: 1.15; font-weight: 500; font-variant-numeric: tabular-nums; }
.ds-passport-stack-year small { display: block; margin-top: 4px; color: var(--surface-muted); font-size: 11px; line-height: 1.4; letter-spacing: 0; }
.ds-passport-example .ds-passport-stack-identity p { margin-top: auto; font-size: 12px; line-height: 1.65; }
.ds-passport-stack-details { display: flex; flex-direction: column; height: 100%; padding: 4px 12px 0; }
.ds-passport-example .ds-passport-stack-details > p { margin: 0; color: var(--surface-ink); font-size: 18px; line-height: 1.35; font-weight: 500; }
.ds-passport-stack-details dl { display: grid; gap: 12px; margin-top: 16px; }
.ds-passport-stack-details dl > div { display: flex; align-items: center; gap: 12px; }
.ds-passport-stack-details dt { font-size: 12px; font-weight: 600; }
.ds-passport-stack-details dd { margin: 2px 0 0; color: var(--surface-muted); font-size: 12px; }
.ds-passport-stack-link { display: inline-flex; align-items: center; align-self: flex-start; gap: 8px; min-height: 44px; margin-top: auto; font-size: 12px; font-weight: 600; }
.ds-passport-stack-options { display: flex; flex-wrap: wrap; gap: 8px; list-style: none; padding: 0; margin: 18px 0 12px; }
.ds-passport-stack-options li { padding: 5px 12px; border-radius: var(--radius-pill); background: var(--surface-subtle); font-size: 12px; }
.ds-passport-stack-status { color: var(--surface-muted); font-size: 12px; }
.ds-passport-example .ds-passport-stack-note { margin-top: 12px; font-size: 12px; line-height: 1.65; }
@media(max-width:1023px){.ds-passport-stack-profile{gap:10px;}}@media(max-width:639px){.ds-passport-stack-identity{padding-right:0;}}@media(max-width:359px){.ds-passport-stack-stage{height:380px;}.ds-passport-stack-card{height:292px;}.ds-passport-stack-content{height:248px;}}@media(prefers-reduced-motion:reduce){.ds-passport-stack-card{transition:none;}}@media(forced-colors:active){.ds-passport-stack-card{outline:1px solid CanvasText;}.ds-passport-stack-trigger[aria-pressed="true"]{text-decoration:underline;}}

.site-footer { width: calc(100% - 48px); margin: 56px auto 16px; padding: 56px 0 35px; overflow: hidden; border-radius: 24px; background: var(--forest); color: var(--cream); }
.site-footer > .container { width: calc(100% - 80px); max-width: none; }
.site-footer .wordmark { display: inline-block; font-size: clamp(2.6rem, 5vw, 3.4rem); line-height: 1; letter-spacing: -.06em; }
.site-footer .wordmark:hover { text-decoration: none; }
.footer-top { display: flex; justify-content: space-between; gap: 48px; padding-bottom: 64px; }
.footer-brand { display: grid; align-content: start; gap: 23px; }
.footer-social-icons { display: flex; flex-wrap: wrap; gap: 8px; }
.footer-social-mark { display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px; border: 1px solid rgb(255 255 255 / 27%); border-radius: 999px; color: var(--cream); }
.footer-navigation { display: flex; flex-wrap: wrap; gap: 44px clamp(36px, 6vw, 88px); }
.footer-nav-group { display: grid; align-content: start; justify-items: start; gap: 11px; min-width: 84px; font-size: .9rem; }
.footer-nav-heading { margin-bottom: 5px; color: #b8ccb9; font-size: .68rem; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; }
.footer-nav-group a { min-height: 28px; text-underline-offset: 5px; }
.footer-nav-group a:hover { text-decoration-thickness: 1px; }
.footer-nav-group a:focus-visible { outline: 2px solid currentColor; outline-offset: 4px; }
.footer-bottom { border-top: 1px solid #4d6955; padding-top: 20px; display: flex; justify-content: space-between; color: #b8ccb9; font-size: .75rem; }

.valora-surface .site-footer { width: calc(100% - 48px); margin: 64px auto 16px; padding: 42px 0 28px; border: 0; border-radius: 24px; background: var(--forest); color: var(--cream); }
.valora-surface .site-footer > .container { width: calc(100% - 80px); max-width: none; }
.valora-surface .footer-top { align-items: flex-start; padding-bottom: 32px; gap: 48px; }
.valora-surface .site-footer .wordmark { font-size: 46px; }
.valora-surface .footer-brand { gap: 20px; }
.valora-surface .footer-social-mark { border-color: rgb(255 255 255 / 27%); color: var(--cream); }
.valora-surface .footer-navigation { gap: 48px clamp(44px, 7vw, 96px); }
.valora-surface .footer-nav-group { min-width: 92px; font-size: 14px; }
.valora-surface .footer-nav-heading { color: #b8ccb9; }
.valora-surface .footer-bottom { padding-top: 20px; border-color: #4d6955; color: #b8ccb9; font-size: 12px; }

.ds-public-footer-example.valora-surface{width:100%;max-width:1440px;min-height:0;margin:0 auto;padding:0;border:0;border-radius:0;background:var(--white,#FFFFFF);color:var(--forest,#1B3A28);--surface:var(--white,#FFFFFF);--surface-line:#E2E8DF;--surface-ink:var(--forest,#1B3A28);--surface-muted:var(--muted,#5B6D60);--font-ui:"Plus Jakarta Sans",Arial,sans-serif;}.ds-public-footer-example .site-footer{box-sizing:border-box;}.ds-public-footer-example .site-footer *{box-sizing:border-box;}@media(max-width:1023px){.ds-public-footer-example.valora-surface .site-footer>.container{width:calc(100% - 64px);}}@media(max-width:639px){.ds-public-footer-example.valora-surface .site-footer{width:calc(100% - 32px);margin:48px auto 16px;padding:34px 0 24px;border-radius:18px;}.ds-public-footer-example.valora-surface .site-footer>.container{width:calc(100% - 56px);}}
.ds-public-footer-example .footer-navigation{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:32px;flex:0 1 780px;min-width:0;width:100%;}.ds-public-footer-example.valora-surface .footer-navigation{gap:32px clamp(24px,3vw,48px);}.ds-public-footer-example .footer-nav-group{gap:8px;min-width:0;}.ds-public-footer-example .footer-nav-group a{display:inline-flex;align-items:center;min-height:32px;max-width:100%;overflow-wrap:anywhere;}@media(max-width:1023px){.ds-public-footer-example .footer-top{flex-direction:column;}.ds-public-footer-example .footer-navigation{grid-template-columns:repeat(2,minmax(0,1fr));flex:none;}}@media(max-width:700px){.ds-public-footer-example .footer-nav-group{gap:0;}.ds-public-footer-example .footer-nav-group a{min-height:44px;padding-block:6px;}}@media(max-width:639px){.ds-public-footer-example.valora-surface .footer-navigation{gap:24px;}.ds-public-footer-example.valora-surface .footer-nav-group{gap:0;font-size:13px;}}
